class Solution {
public:
    vector<int> findAnagrams(string s, string p) {
        int ns = s.length(), np = p.length();
        if (np > ns) return {};
        vector<int> cp(26, 0), cs(26, 0), ans;
        for (int i = 0; i < np; i++) {
            cp[p[i] - 'a']++;
            cs[s[i] - 'a']++;
        }
        if (cp == cs) ans.push_back(0);
        for (int i = np; i < ns; i++) {
            cs[s[i] - 'a']++;
            cs[s[i - np] - 'a']--;
            if (cp == cs) ans.push_back(i - np + 1);
        }
        return ans;
    }
};

class Solution {
    public List<Integer> findAnagrams(String s, String p) {
        int ns = s.length(), np = p.length();
        List<Integer> ans = new ArrayList<>();
        if (np > ns) return ans;
        int[] cp = new int[26];
        int[] cs = new int[26];
        for (int i = 0; i < np; i++) {
            cp[p.charAt(i) - 'a']++;
            cs[s.charAt(i) - 'a']++;
        }
        if (matches(cp, cs)) ans.add(0);
        for (int i = np; i < ns; i++) {
            cs[s.charAt(i) - 'a']++;
            cs[s.charAt(i - np) - 'a']--;
            if (matches(cp, cs)) ans.add(i - np + 1);
        }
        return ans;
    }
    private boolean matches(int[] a, int[] b) {
        for (int i = 0; i < 26; i++) if (a[i] != b[i]) return false;
        return true;
    }
}

var findAnagrams = function(s, p) {
    const ns = s.length, np = p.length;
    if (np > ns) return [];
    const cp = new Array(26).fill(0);
    const cs = new Array(26).fill(0);
    for (let i = 0; i < np; i++) {
        cp[p.charCodeAt(i) - 97]++;
        cs[s.charCodeAt(i) - 97]++;
    }
    function matches() {
        for (let i = 0; i < 26; i++) if (cp[i] !== cs[i]) return false;
        return true;
    }
    const ans = [];
    if (matches()) ans.push(0);
    for (let i = np; i < ns; i++) {
        cs[s.charCodeAt(i) - 97]++;
        cs[s.charCodeAt(i - np) - 97]--;
        if (matches()) ans.push(i - np + 1);
    }
    return ans;
};
